import re,os,collections
root='AlgebraicJacobian'
def mod2path(m):
    return m.replace('.','/')+'.lean'
imports={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            m=p[:-5].replace('/','.')
            ims=[]
            for line in open(p):
                mo=re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)
                if mo: ims.append(mo.group(1))
                if line.startswith('/-!') or line.startswith('namespace'): break
            imports[m]=ims
def closure(t):
    seen=set(); stack=[t]
    while stack:
        m=stack.pop()
        if m in seen: continue
        seen.add(m)
        for i in imports.get(m,[]): stack.append(i)
    return seen
for t in ['AlgebraicJacobian.RiemannRoch.ChiLedger','AlgebraicJacobian.RiemannRoch.ChiFiniteness','AlgebraicJacobian.RiemannRoch.UniformVanishing','AlgebraicJacobian.Cohomology.Finiteness','AlgebraicJacobian.RiemannRoch.SectionBound','AlgebraicJacobian.RiemannRoch.ChiCurve','AlgebraicJacobian.RiemannRoch.Degree','AlgebraicJacobian.RiemannRoch.JumpDimension']:
    if t not in imports: print(t,'MISSING'); continue
    c=closure(t)
    lines=sum(sum(1 for _ in open(mod2path(m))) for m in c)
    print(f"{t}: {len(c)} files, {lines} lines")
EOF

